body:
{"op":"state","id":"selected","initial":"root"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"title","parent":"panel","type":"text","text":"企业 CA 证书链"}
{"op":"node","id":"choice","parent":"panel","type":"choice","state":"selected","options":[{"value":"root","label":"根证书"},{"value":"server","label":"服务器证书"}]}
{"op":"node","id":"root-detail","parent":"panel","type":"text","text":"根证书是信任起点。","visibleWhen":{"state":"selected","equals":"root"}}
{"op":"node","id":"explain","parent":"panel","type":"button","label":"继续解释","action":{"type":"draft","text":"请继续解释 {{selected}}"}}
{"op":"end"}

{"op":"state","id":"mode","initial":"symmetric"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"choice","parent":"panel","type":"choice","state":"mode","options":[{"value":"symmetric","label":"对称加密"},{"value":"asymmetric","label":"非对称加密"}]}
{"op":"node","id":"detail","parent":"panel","type":"text","text":"选择一种模式查看说明。","visibleWhen":{"state":"mode","equals":"symmetric"}}
{"op":"end"}

{"op":"state","id":"risk","initial":"medium"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"risk-choice","parent":"panel","type":"choice","state":"risk","options":[{"value":"low","label":"低风险"},{"value":"medium","label":"中风险"},{"value":"high","label":"高风险"}]}
{"op":"node","id":"advice","parent":"panel","type":"text","text":"中风险建议开启多因素认证。","visibleWhen":{"state":"risk","equals":"medium"}}
{"op":"end"}

{"op":"state","id":"index","initial":"btree"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"index-choice","parent":"panel","type":"choice","state":"index","options":[{"value":"btree","label":"B-tree"},{"value":"hash","label":"Hash"}]}
{"op":"node","id":"index-text","parent":"panel","type":"text","text":"B-tree 适合范围查询。","visibleWhen":{"state":"index","equals":"btree"}}
{"op":"end"}

{"op":"state","id":"budget","initial":"standard"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"budget-choice","parent":"panel","type":"choice","state":"budget","options":[{"value":"economy","label":"经济"},{"value":"standard","label":"标准"},{"value":"premium","label":"舒适"}]}
{"op":"node","id":"budget-text","parent":"panel","type":"text","text":"标准档位适合大多数行程。"}
{"op":"end"}

{"op":"state","id":"pace","initial":"steady"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"pace-choice","parent":"panel","type":"choice","state":"pace","options":[{"value":"light","label":"轻量"},{"value":"steady","label":"稳定"},{"value":"intensive","label":"强化"}]}
{"op":"node","id":"pace-text","parent":"panel","type":"text","text":"稳定计划每天学习 30 分钟。"}
{"op":"end"}

{"op":"state","id":"retention","initial":"30d"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"retention-choice","parent":"panel","type":"choice","state":"retention","options":[{"value":"7d","label":"7 天"},{"value":"30d","label":"30 天"},{"value":"90d","label":"90 天"}]}
{"op":"node","id":"retention-text","parent":"panel","type":"text","text":"保留 30 天可以平衡排障和成本。"}
{"op":"end"}

{"op":"state","id":"format","initial":"markdown"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"format-choice","parent":"panel","type":"choice","state":"format","options":[{"value":"markdown","label":"Markdown"},{"value":"text","label":"纯文本"}]}
{"op":"node","id":"format-text","parent":"panel","type":"text","text":"Markdown 会保留标题和列表结构。","visibleWhen":{"state":"format","equals":"markdown"}}
{"op":"end"}

{"op":"state","id":"subject","initial":"example.com"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"prompt","parent":"panel","type":"text","text":"输入证书主题名称。"}
{"op":"node","id":"subject-input","parent":"panel","type":"input","state":"subject","placeholder":"例如 example.com"}
{"op":"node","id":"explain","parent":"panel","type":"button","label":"生成说明","action":{"type":"draft","text":"请解释证书主题 {{subject}}"}}
{"op":"end"}

{"op":"state","id":"city","initial":"上海"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"city-input","parent":"panel","type":"input","state":"city","placeholder":"输入城市"}
{"op":"node","id":"plan","parent":"panel","type":"button","label":"规划","action":{"type":"draft","text":"请规划 {{city}} 的两日行程"}}
{"op":"end"}

{"op":"state","id":"query","initial":"timeout"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"query-input","parent":"panel","type":"input","state":"query","placeholder":"错误关键词"}
{"op":"node","id":"search","parent":"panel","type":"button","label":"查找","action":{"type":"draft","text":"请分析日志关键词 {{query}}"}}
{"op":"end"}

{"op":"state","id":"amount","initial":"10000"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"amount-input","parent":"panel","type":"input","state":"amount","placeholder":"目标金额"}
{"op":"node","id":"advice","parent":"panel","type":"button","label":"给建议","action":{"type":"draft","text":"请根据目标金额 {{amount}} 给储蓄建议"}}
{"op":"end"}

{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"heading","parent":"panel","type":"text","text":"证书链示意图"}
{"op":"node","id":"diagram","parent":"panel","type":"asset","ref":"ca-chain"}
{"op":"end"}

{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"heading","parent":"panel","type":"text","text":"请求时序"}
{"op":"node","id":"diagram","parent":"panel","type":"asset","ref":"request-sequence"}
{"op":"end"}

{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"heading","parent":"panel","type":"text","text":"部署拓扑"}
{"op":"node","id":"topology","parent":"panel","type":"asset","ref":"deployment-topology"}
{"op":"end"}

{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"heading","parent":"panel","type":"text","text":"空间模型"}
{"op":"node","id":"model","parent":"panel","type":"asset","ref":"room-model"}
{"op":"end"}

{"op":"state","id":"node","initial":"root"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"node-choice","parent":"panel","type":"choice","state":"node","options":[{"value":"root","label":"根证书"},{"value":"leaf","label":"叶证书"}]}
{"op":"node","id":"diagram","parent":"panel","type":"asset","ref":"cert-chain"}
{"op":"node","id":"explain","parent":"panel","type":"button","label":"解释节点","action":{"type":"draft","text":"请解释证书节点 {{node}}"}}
{"op":"end"}

{"op":"state","id":"env","initial":"staging"}
{"op":"state","id":"service","initial":"api"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"env-choice","parent":"panel","type":"choice","state":"env","options":[{"value":"staging","label":"测试"},{"value":"production","label":"生产"}]}
{"op":"node","id":"service-input","parent":"panel","type":"input","state":"service","placeholder":"服务名"}
{"op":"node","id":"diagram","parent":"panel","type":"asset","ref":"deploy-flow"}
{"op":"node","id":"continue","parent":"panel","type":"button","label":"继续","action":{"type":"draft","text":"请分析 {{env}} 环境的 {{service}} 服务"}}
{"op":"end"}

{"op":"state","id":"source","initial":"logs"}
{"op":"state","id":"filter","initial":"error"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"source-choice","parent":"panel","type":"choice","state":"source","options":[{"value":"logs","label":"日志"},{"value":"traces","label":"链路"}]}
{"op":"node","id":"filter-input","parent":"panel","type":"input","state":"filter","placeholder":"过滤条件"}
{"op":"node","id":"diagram","parent":"panel","type":"asset","ref":"observability"}
{"op":"node","id":"query","parent":"panel","type":"button","label":"查询","action":{"type":"draft","text":"请查询 {{source}} 中满足 {{filter}} 的记录"}}
{"op":"end"}

{"op":"state","id":"stage","initial":"beginner"}
{"op":"state","id":"goal","initial":"掌握基础"}
{"op":"node","id":"panel","type":"column"}
{"op":"node","id":"stage-choice","parent":"panel","type":"choice","state":"stage","options":[{"value":"beginner","label":"入门"},{"value":"advanced","label":"进阶"}]}
{"op":"node","id":"goal-input","parent":"panel","type":"input","state":"goal","placeholder":"学习目标"}
{"op":"node","id":"diagram","parent":"panel","type":"asset","ref":"learning-map"}
{"op":"node","id":"start","parent":"panel","type":"button","label":"开始规划","action":{"type":"draft","text":"为 {{stage}} 阶段规划目标：{{goal}}"}}
{"op":"end"}
